def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    width = min(len(left[0]), len(right[0]))
    lbg = Counter(x for row in left for x in row).most_common(1)[0][0]
    rbg = Counter(x for row in right for x in row).most_common(1)[0][0]
    # When both panels share a background, union their foreground masks.
    # When they differ, retain the left-panel foreground pattern, using
    # the right-panel background and removing points adjacent to right marks.
    if lbg == rbg:
        return [[2 if left[r][c] != lbg or right[r][c] != rbg else 3
                 for c in range(width)] for r in range(h)]
